CREATE TABLE users(id uuid PRIMARY KEY, email varchar(254) UNIQUE NOT NULL, name varchar(120) NOT NULL, password_hash text NOT NULL, system_role varchar(20) NOT NULL DEFAULT 'USER', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE password_resets(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, used boolean NOT NULL DEFAULT false);
CREATE TABLE bereavement_cases(id uuid PRIMARY KEY, title varchar(200) NOT NULL, created_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), status varchar(20) NOT NULL DEFAULT 'ACTIVE', retention_requested_at timestamptz);
CREATE TABLE deceased_profiles(case_id uuid PRIMARY KEY REFERENCES bereavement_cases, full_name varchar(120) NOT NULL, date_of_birth date, date_of_death date NOT NULL, city varchar(120), state varchar(120), relationship varchar(60) NOT NULL, pan_last_four varchar(4), aadhaar_last_four varchar(4), mobile_numbers text NOT NULL DEFAULT '', email_addresses text NOT NULL DEFAULT '', known_services text NOT NULL DEFAULT '');
CREATE TABLE case_members(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, user_id uuid REFERENCES users, invited_email varchar(254), role varchar(30) NOT NULL CHECK(role IN ('CASE_OWNER','FAMILY_ADMIN','CONTRIBUTOR','VIEWER','PROFESSIONAL_ADVISOR')), status varchar(20) NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(case_id,user_id), UNIQUE(case_id,invited_email));
CREATE TABLE providers(id uuid PRIMARY KEY, name varchar(120) UNIQUE NOT NULL, category varchar(60) NOT NULL, website text NOT NULL, support_contact text, grievance_contact text, supported_actions text NOT NULL, adapter_type varchar(30) NOT NULL, additional_rules text NOT NULL DEFAULT 'DEMO: confirm requirements with the provider.', estimated_days integer NOT NULL DEFAULT 10 CHECK(estimated_days > 0), escalation_rules text NOT NULL DEFAULT 'DEMO: suggest follow-up two days after estimated response.', verification_requirements text NOT NULL DEFAULT 'Provider verification required', notes text NOT NULL DEFAULT 'DEMO configuration; not official procedures.', last_verified_at timestamptz, demo boolean NOT NULL DEFAULT true);
CREATE TABLE provider_requirements(id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES providers, category varchar(60) NOT NULL, description text NOT NULL, UNIQUE(provider_id,category));
CREATE TABLE provider_adapters(id uuid PRIMARY KEY, provider_id uuid NOT NULL UNIQUE REFERENCES providers, mode varchar(30) NOT NULL, enabled boolean NOT NULL DEFAULT false);
CREATE TABLE provider_cases(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, provider_id uuid NOT NULL REFERENCES providers, action varchar(60) NOT NULL, assigned_to uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(case_id,provider_id,action));
CREATE TABLE workflow_instances(id uuid PRIMARY KEY REFERENCES provider_cases, state varchar(60) NOT NULL, version bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, demo_step integer NOT NULL DEFAULT 0);
CREATE TABLE workflow_events(id uuid PRIMARY KEY, provider_case_id uuid NOT NULL REFERENCES provider_cases, actor_id uuid REFERENCES users, from_state varchar(60), to_state varchar(60) NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, filename varchar(240) NOT NULL, category varchar(60) NOT NULL, mime_type varchar(80) NOT NULL, checksum varchar(64) NOT NULL, storage_path text NOT NULL, uploaded_by uuid NOT NULL REFERENCES users, uploaded_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, is_original boolean NOT NULL DEFAULT true, status varchar(30) NOT NULL DEFAULT 'AVAILABLE', extracted_metadata jsonb NOT NULL DEFAULT '{}', size_bytes bigint NOT NULL, expires_at timestamptz);
CREATE TABLE document_versions(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES documents, version integer NOT NULL, storage_path text NOT NULL, checksum varchar(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,version));
CREATE TABLE document_access_logs(id uuid PRIMARY KEY, document_id uuid NOT NULL REFERENCES documents, actor_id uuid NOT NULL REFERENCES users, action varchar(60) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consents(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, provider_case_id uuid NOT NULL REFERENCES provider_cases, actor_id uuid NOT NULL REFERENCES users, document_ids jsonb NOT NULL, purpose text NOT NULL, shared_fields jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, consumed_at timestamptz);
CREATE TABLE correspondence(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, provider_case_id uuid REFERENCES provider_cases, author_id uuid REFERENCES users, kind varchar(30) NOT NULL, subject varchar(200) NOT NULL, body text NOT NULL, reference varchar(120), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE correspondence_attachments(correspondence_id uuid REFERENCES correspondence, document_id uuid REFERENCES documents, PRIMARY KEY(correspondence_id,document_id));
CREATE TABLE tasks(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, provider_case_id uuid REFERENCES provider_cases, title varchar(200) NOT NULL, assigned_to uuid REFERENCES users, due_at timestamptz, status varchar(20) NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deadlines(id uuid PRIMARY KEY, provider_case_id uuid NOT NULL REFERENCES provider_cases, kind varchar(40) NOT NULL, source varchar(30) NOT NULL CHECK(source IN ('OFFICIAL','PROVIDER_DEFINED','SYSTEM_ESTIMATE')), due_at timestamptz NOT NULL, reminded_at timestamptz, escalated_at timestamptz, resolved boolean NOT NULL DEFAULT false);
CREATE TABLE notifications(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, case_id uuid REFERENCES bereavement_cases, title varchar(200) NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id uuid PRIMARY KEY, actor_id uuid REFERENCES users, case_id uuid REFERENCES bereavement_cases, provider_case_id uuid REFERENCES provider_cases, action varchar(80) NOT NULL, entity_type varchar(60) NOT NULL, entity_id uuid, before_state jsonb NOT NULL DEFAULT '{}', after_state jsonb NOT NULL DEFAULT '{}', correlation_id varchar(64), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE discovered_accounts(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, provider_id uuid NOT NULL REFERENCES providers, source varchar(30) NOT NULL, status varchar(20) NOT NULL DEFAULT 'POSSIBLE' CHECK(status IN ('POSSIBLE','CONFIRMED','IGNORED')), hint text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(case_id,provider_id));
CREATE TABLE ai_analysis(id uuid PRIMARY KEY, case_id uuid NOT NULL REFERENCES bereavement_cases, document_id uuid REFERENCES documents, type varchar(60) NOT NULL, output jsonb NOT NULL, provider varchar(60) NOT NULL DEFAULT 'DETERMINISTIC_MOCK', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events(id uuid PRIMARY KEY, aggregate_id uuid NOT NULL, case_id uuid REFERENCES bereavement_cases, topic varchar(120) NOT NULL, payload jsonb NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0, failed_at timestamptz);
CREATE TABLE consumed_events(consumer varchar(80) NOT NULL, event_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer,event_id));
CREATE TABLE submission_keys(provider_case_id uuid NOT NULL REFERENCES provider_cases, key varchar(120) NOT NULL, actor_id uuid NOT NULL REFERENCES users, consent_id uuid NOT NULL REFERENCES consents, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider_case_id,key));
CREATE TABLE admin_configuration(key varchar(120) PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX member_user_idx ON case_members(user_id,case_id);
CREATE INDEX provider_case_case_idx ON provider_cases(case_id);
CREATE INDEX documents_case_idx ON documents(case_id,status);
CREATE INDEX audit_case_time_idx ON audit_events(case_id,created_at);
CREATE INDEX workflow_event_time_idx ON workflow_events(provider_case_id,created_at);
CREATE INDEX outbox_pending_idx ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE INDEX deadline_pending_idx ON deadlines(due_at) WHERE NOT resolved;
CREATE INDEX notification_user_idx ON notifications(user_id,created_at);
CREATE INDEX tasks_case_idx ON tasks(case_id,status);
CREATE INDEX correspondence_case_idx ON correspondence(case_id,created_at);
CREATE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER workflow_append_only BEFORE UPDATE OR DELETE ON workflow_events FOR EACH ROW EXECUTE FUNCTION immutable_history();
